#!/usr/bin/env node
'use strict';
/**
 * PreToolUse gate. Matcher: Bash|Edit|Write|MultiEdit|NotebookEdit|Read
 *
 * Guards (each can be turned off in config.json / <project>/.claude/rn-hooks.json):
 *  guardNativeDirs     — Expo CNG projects: deny edits in ios/ and android/ (generated by prebuild)
 *  guardExpoInstall    — Expo projects: deny `npm install <pkg>` / `yarn add` / `pnpm add` / `bun add`, point to `npx expo install`
 *  guardSecrets        — deny reading/editing .env, keystores, signing keys; ask for Firebase config files and shell access to them
 *  guardLockfiles      — deny hand-editing lockfiles and node_modules
 *  guardCloudCommands  — ask before `eas build|submit|update|…` (stronger warning for production updates)
 *  guardGitPush        — ask before `git push`; deny force-push
 *
 * Read-only commands (eas build:list, npm view/ls/audit, expo install --check/--fix, git status…) are never blocked.
 */
const path = require('path');
const c = require('./lib/common');

// ---------- shell parsing ----------

/** Split a shell command into simple-command segments, each as an argv array (best effort). */
function segments(command) {
  const segs = [];
  let cur = [];
  let tok = '';
  let q = null;
  let hasTok = false;
  const push = () => { if (hasTok) { cur.push(tok); tok = ''; hasTok = false; } };
  const end = () => { push(); if (cur.length) segs.push(cur); cur = []; };
  for (let i = 0; i < command.length; i++) {
    const ch = command[i];
    if (q) {
      if (ch === q) q = null;
      else if (ch === '\\' && q === '"' && i + 1 < command.length) { tok += command[++i]; }
      else tok += ch;
      continue;
    }
    if (ch === '"' || ch === "'") { q = ch; hasTok = true; continue; }
    if (ch === '\\' && i + 1 < command.length) { tok += command[++i]; hasTok = true; continue; }
    if (/\s/.test(ch) && ch !== '\n') { push(); continue; }
    if (ch === '\n' || ch === ';' || ch === '|' || ch === '&' || ch === '(' || ch === ')' || ch === '`') {
      end();
      continue;
    }
    if (ch === '$' && command[i + 1] === '(') { end(); i++; continue; }
    tok += ch; hasTok = true;
  }
  end();
  // strip leading env assignments and wrappers
  return segs.map((argv) => {
    let a = argv.slice();
    while (a.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(a[0])) a.shift();
    while (a.length && ['sudo', 'command', 'exec', 'nohup', 'time', 'env'].includes(a[0])) {
      a.shift();
      while (a.length && (/^-/.test(a[0]) || /^[A-Za-z_][A-Za-z0-9_]*=/.test(a[0]))) a.shift();
    }
    return a;
  }).filter((a) => a.length);
}

/** Normalize `npx eas …`, `pnpm exec eas …`, `yarn eas …`, `bunx eas …` → ['eas', …] */
function unwrapRunner(argv) {
  const a = argv.slice();
  if ((a[0] === 'npx' || a[0] === 'bunx' || a[0] === 'pnpx')) {
    a.shift();
    while (a.length && a[0].startsWith('-')) a.shift();
  } else if ((a[0] === 'pnpm' || a[0] === 'yarn' || a[0] === 'bun' || a[0] === 'npm') && (a[1] === 'exec' || a[1] === 'dlx' || a[1] === 'x')) {
    a.splice(0, 2);
    while (a.length && a[0].startsWith('-')) a.shift();
  }
  if (a[0] === 'eas-cli') a[0] = 'eas';
  if (a[0] && /(^|\/)eas$/.test(a[0])) a[0] = 'eas';
  if (a[0] && /(^|\/)git$/.test(a[0])) a[0] = 'git';
  return a;
}

// ---------- secrets ----------

const SAFE_ENV = /\.(example|sample|template|defaults|dist)$/i;
function secretKind(p) {
  if (!p) return null;
  const base = path.basename(p);
  if (/^\.env(\..+)?$/i.test(base) && !SAFE_ENV.test(base)) return 'env';
  if (/\.(keystore|jks|p8|p12|pfx|mobileprovision|pem|cer)$/i.test(base)) return 'signing';
  if (/^(key|keystore|signing)\.properties$/i.test(base)) return 'signing';
  if (/^credentials\.json$/i.test(base) || /service[-_]?account.*\.json$/i.test(base)) return 'credentials';
  if (/^(google-services\.json|GoogleService-Info\.plist)$/i.test(base)) return 'firebase';
  return null;
}

const SHELL_READERS = new Set([
  'cat', 'less', 'more', 'head', 'tail', 'bat', 'grep', 'rg', 'ag', 'sed', 'awk', 'cut', 'sort', 'uniq', 'strings',
  'xxd', 'hexdump', 'od', 'base64', 'cp', 'mv', 'scp', 'rsync', 'curl', 'wget', 'source', '.', 'open', 'code',
  'vim', 'vi', 'nano', 'emacs', 'jq', 'yq', 'plutil', 'keytool', 'openssl', 'tee', 'dd', 'xargs', 'diff', 'zip', 'tar',
]);

// ---------- guards ----------

function guardEditTools(input, cfg, stack) {
  const file = c.toolFilePath(input);
  if (!file) return;
  const abs = path.resolve(input.cwd || process.cwd(), file);
  const tool = input.tool_name;
  const isWrite = tool !== 'Read';

  if (cfg.guardSecrets) {
    const kind = secretKind(abs);
    if (kind === 'firebase') {
      if (isWrite) c.deny(`${path.basename(abs)} is downloaded from the Firebase console and must not be edited by hand. Ask the user to replace the file if its contents are wrong.`);
      c.ask(`${path.basename(abs)} contains Firebase project config (API key, project IDs). Allow reading it?`);
    }
    if (kind) {
      const what = { env: 'environment secrets', signing: 'app signing keys/certificates', credentials: 'service credentials' }[kind];
      c.deny(`${path.basename(abs)} holds ${what} and is protected. Don't read or modify it. If you need to know which variables exist, use .env.example or ask the user; to change values, tell the user exactly what to change.`);
    }
  }

  if (!isWrite) return;

  if (cfg.guardLockfiles) {
    const base = path.basename(abs);
    if (/^(package-lock\.json|yarn\.lock|pnpm-lock\.yaml|bun\.lockb?|npm-shrinkwrap\.json|Podfile\.lock|Gemfile\.lock)$/.test(base)) {
      c.deny(`${base} is generated. Don't edit it by hand — change package.json / Podfile and run the package manager (or pod install) to regenerate it.`);
    }
    if (abs.split(path.sep).includes('node_modules')) {
      c.deny('Files in node_modules are overwritten on every install. If a library really needs a fix, propose patch-package (or a fork / upgrade) to the user instead of editing node_modules.');
    }
  }

  if (cfg.guardNativeDirs && stack && c.isCNG(stack)) {
    const rel = c.relInside(stack.projectRoot, abs);
    if (rel && (rel.startsWith('ios/') || rel.startsWith('android/'))) {
      c.deny(`This is an Expo CNG project (${stack.workflow}): ios/ and android/ are generated by \`npx expo prebuild\` and changes here are lost. Make the change in ${stack.appConfig || 'app.json / app.config'} (e.g. ios.infoPlist, android.permissions), via expo-build-properties, or a config plugin, then run \`npx expo prebuild --clean\`.`);
    }
  }
}

function guardBash(input, cfg, stack) {
  const command = String((input.tool_input && input.tool_input.command) || '');
  if (!command.trim()) return;
  const segs = segments(command).map(unwrapRunner);

  // secrets via shell (ask — there are legit cases like `cp .env.example .env`)
  if (cfg.guardSecrets) {
    const redirect = command.match(/>{1,2}\s*["']?([^\s"';&|]+)/g) || [];
    const redirectTargets = redirect.map((r) => r.replace(/^>{1,2}\s*["']?/, ''));
    for (const t of redirectTargets) {
      const k = secretKind(t);
      if (k && k !== 'firebase') c.ask(`This command writes to ${path.basename(t)} (protected secrets file). Allow?`);
    }
    for (const argv of segs) {
      const cmd = path.basename(argv[0] || '');
      if (!SHELL_READERS.has(cmd)) continue;
      const hit = argv.slice(1).find((a) => secretKind(a.replace(/^@/, '')));
      if (hit) c.ask(`\`${cmd}\` touches ${path.basename(hit)}, a protected secrets file. Allow?`);
    }
  }

  for (const argv of segs) {
    const [bin, sub] = argv;

    // ---- Expo: install via `npx expo install` ----
    if (cfg.guardExpoInstall && stack && c.isExpo(stack)) {
      const pm = path.basename(bin || '');
      const addCmd =
        (pm === 'npm' && ['install', 'i', 'add', 'isntall', 'in'].includes(sub)) ||
        (pm === 'yarn' && sub === 'add') ||
        (pm === 'pnpm' && ['add', 'install', 'i'].includes(sub)) ||
        (pm === 'bun' && ['add', 'install', 'i'].includes(sub));
      if (addCmd) {
        const rest = argv.slice(2);
        const global = rest.some((a) => ['-g', '--global', '--location=global'].includes(a));
        const pkgs = rest.filter((a) => !a.startsWith('-'));
        if (pkgs.length && !global) {
          const dev = rest.some((a) => ['-D', '--save-dev', '--dev', '-d'].includes(a));
          c.deny(`Expo project: install packages with \`npx expo install ${pkgs.join(' ')}${dev ? ' -- --save-dev' : ''}\` so versions match Expo SDK ${stack.versions.expoSdk || ''}. It works for non-SDK packages too (installs latest) and uses the project's package manager (${stack.packageManager}).`);
        }
      }
    }

    // ---- EAS cloud / irreversible commands ----
    if (cfg.guardCloudCommands && bin === 'eas') {
      const s = sub || '';
      const args = argv.slice(2);
      const flag = (names) => {
        for (let i = 0; i < args.length; i++) {
          for (const n of names) {
            if (args[i] === n) return args[i + 1] || '';
            if (args[i].startsWith(`${n}=`)) return args[i].slice(n.length + 1);
          }
        }
        return null;
      };
      if (s === 'update') {
        const target = flag(['--channel', '--branch']) || '';
        if (/^prod(uction)?$/i.test(target) || args.includes('--auto') && /prod/i.test(command)) {
          c.ask(`⚠️ OTA update to PRODUCTION (${target || 'auto'}): this ships JS to all users of matching binaries immediately. Confirm the runtime version matches the store build and the change is JS-only.`);
        }
        c.ask(`eas update publishes an OTA update${target ? ` to "${target}"` : ''}. Confirm?`);
      }
      if (s === 'build') c.ask('eas build starts a cloud build (uses build credits / queue time). Confirm the platform and profile?');
      if (s === 'submit') c.ask('eas submit uploads a build to App Store Connect / Google Play. Confirm?');
      if (/^(update:(republish|rollback|delete|revert-update-rollout|edit)|channel:(edit|delete|rollout|pause|resume)|branch:(delete|rename)|env:(create|update|delete|push)|secret:(create|delete|push)|credentials.*|device:delete|webhook:(create|update|delete)|project:init|init)$/.test(s)) {
        c.ask(`\`eas ${s}\` changes cloud state or credentials. Confirm?`);
      }
    }

    // ---- git push ----
    if (cfg.guardGitPush && bin === 'git') {
      // skip global options: -C <dir>, -c <k=v>, --git-dir=..., --no-pager, etc.
      let i = 1;
      while (i < argv.length && argv[i].startsWith('-')) {
        if (['-C', '-c', '--git-dir', '--work-tree', '--namespace'].includes(argv[i])) i += 2; else i += 1;
      }
      if (argv[i] === 'push') {
        const rest = argv.slice(i + 1);
        const force = rest.some((a) => a === '--force' || a === '-f' || /^-[a-zA-Z]*f/.test(a) && !a.startsWith('--') || a === '--mirror' || /^\+/.test(a));
        if (force) c.deny('Force-push is blocked: it rewrites remote history. If it is really needed (e.g. after an interactive rebase on a personal branch), the user can run it themselves; --force-with-lease is the safer form.');
        const del = rest.some((a) => a === '--delete' || a === '-d' || /^:/.test(a));
        if (del) c.ask('This push deletes a remote branch/tag. Confirm?');
        c.ask(`git push${rest.length ? ` ${rest.join(' ')}` : ''} — confirm pushing to the remote?`);
      }
    }
  }
}

c.safe(() => {
  const input = c.readInput();
  const tool = input.tool_name;
  if (!tool) c.ok();
  const cwd = input.cwd || process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const fileArg = c.toolFilePath(input);
  const stack = c.getStack(fileArg ? path.dirname(path.resolve(cwd, fileArg)) : cwd);
  const cfg = c.getConfig(stack && stack.projectRoot);

  if (tool === 'Bash') guardBash(input, cfg, stack);
  else if (['Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Read'].includes(tool)) guardEditTools(input, cfg, stack);
  c.ok();
});
